    "question": "L'évaluation de la gravité de la déshydratation chez l'enfant :",
    "propositions": {
      "A": "Perte de poids (< 5 %) du poids corporel constitue une déshydratation légère et qui ne s'accompagne pas souvent de symptomatologie clinique.",
      "B": "La perte de poids doit être obligatoirement (< 2,5 %) du poids corporel pour parler d'une déshydratation légère.",
      "C": "La perte de poids (5–10 %) du poids corporel constitue une déshydratation modérée ; les signes cliniques sont habituellement francs.",
      "D": "La perte de poids doit être obligatoirement (5–10 %) du poids corporel pour parler d'une déshydratation sévère.",
      "E": "La perte de poids > 10 % du poids corporel constitue une déshydratation sévère, présence des signes d'état de choc hypovolémique avec des complications, surtout si elle > 15 %."
    },
    "question_fr": "L'évaluation de la gravité de la déshydratation chez l'enfant :",
    "bonnes_reponses": [
      "A",
      "C",
      "E"
    ],
